import subprocess, json as J, unicodedata
def gron_key(w):
    s = J.dumps({w:1}, ensure_ascii=False).encode('utf-8')
    p = subprocess.run(["./executable"], input=s, capture_output=True)
    out = p.stdout.decode()
    lines = out.splitlines()
    return lines[1] if len(lines)>1 else out.strip()

# test Pc chars
pcs = ["\u005f", "\u203f", "\u2040", "\u2054", "\ufe33", "\ufe34", "\ufe4d", "\ufe4e", "\ufe4f", "\uff3f"]
for ch in pcs:
    try: name = unicodedata.name(ch)
    except: name="?"
    print(f"U+{ord(ch):04X} {name:30} single=> {gron_key(ch)!r} after-a=> {gron_key('a'+ch)!r}")

print("--- Mc/Mn/Me ---")
for ch in ["\u0903", "\u093e", "\u093f", "\u0300", "\u0301", "\u036f", "\u20d0", "\u20dd", "\ufe20", "\ufe26"]:
    try: name = unicodedata.name(ch)
    except: name="?"
    cat = unicodedata.category(ch)
    print(f"U+{ord(ch):04X} cat={cat} {name:30} single=> {gron_key(ch)!r} after-a=> {gron_key('a'+ch)!r}")

print("--- Nl/No ---")
for ch in ["\u2163", "\u2164", "\u16e0", "\u00b2", "\u00bd", "\u2150", "\u0400"]:
    try: name = unicodedata.name(ch)
    except: name="?"
    cat = unicodedata.category(ch)
    print(f"U+{ord(ch):04X} cat={cat} {name:30} single=> {gron_key(ch)!r} after-a=> {gron_key('a'+ch)!r}")

print("--- L ---")
for ch in ["A", "z", "\u00aa", "\u00b5", "\u00c0", "\u00df", "\u037a", "\u03b1", "\u4e2d", "\U0001D400"]:
    try: name = unicodedata.name(ch)
    except: name="?"
    cat = unicodedata.category(ch)
    print(f"U+{ord(ch):04X} cat={cat} {name:30} single=> {gron_key(ch)!r} after-a=> {gron_key('a'+ch)!r}")

print("--- Cf ---")
for ch in ["\u200c", "\u200d", "\u200e", "\u200f", "\u00ad"]:
    try: name = unicodedata.name(ch)
    except: name="?"
    cat = unicodedata.category(ch)
    print(f"U+{ord(ch):04X} cat={cat} {name:30} single=> {gron_key(ch)!r} after-a=> {gron_key('a'+ch)!r}")
PY
"}

