import subprocess, json as J, unicodedata
def gron_key(w):
    s = J.dumps({w:1}, ensure_ascii=False).encode('utf-8')
    p = subprocess.run(["./executable"], input=s, capture_output=True)
    out = p.stdout.decode()
    lines = out.splitlines()
    return lines[1] if len(lines)>1 else out.strip()

# Other_ID_Start per Unicode: 2118, 212E, 309B, 309C
for ch in ["\u2118", "\u212e", "\u309b", "\u309c"]:
    try: name=unicodedata.name(ch)
    except: name="?"
    print(f"U+{ord(ch):04X} {name} cat={unicodedata.category(ch)} single=> {gron_key(ch)!r} after-a=> {gron_key('a'+ch)!r} mid=> {gron_key('a'+ch+'b')!r}")

print("--- Other_ID_Continue candidates: 00B7, 0387, 1369, 19DA ---")
for ch in ["\u00b7", "\u0387", "\u1369", "\u19da", "\u30fb"]:
    try: name=unicodedata.name(ch)
    except: name="?"
    print(f"U+{ord(ch):04X} {name} cat={unicodedata.category(ch)} single=> {gron_key(ch)!r} after-a=> {gron_key('a'+ch)!r} mid=> {gron_key('a'+ch+'b')!r}")

print("--- middle dot detailed ---")
for w in ["a\u00b7", "a\u00b7b", "\u00b7", "a\u0387", "a\u0387b"]:
    print(f"{w!r} => {gron_key(w)!r}")

print("--- Nd vs Nl ---")
for ch in ["0", "\u0660", "\u00b2", "\u2163"]:
    print(f"U+{ord(ch):04X} cat={unicodedata.category(ch)} single=> {gron_key(ch)!r} after-a=> {gron_key('a'+ch)!r}")

# test underscore variants and dollar
print("--- Pc detailed single vs after ---")
for ch in ["_", "\u203f", "\u00b7"]:
    print(f"U+{ord(ch):04X} single {gron_key(ch)!r} a+ch {gron_key('a'+ch)!r}")
PY
"}

