import subprocess
def ungron(inp, args=["--ungron"]):
    p = subprocess.run(["./executable"]+args, input=inp, capture_output=True)
    return p.returncode, p.stdout, p.stderr

tests = [
    b'json = 1;
json = 2;
',
    b'json = {};
json.a = {};
json.a.b = 1;
',
    b'json.a.b = 1;
',  # implicit intermediate?
    b'json[0] = 1;
',  # no root, array?
    b'json[0].a = 1;
',
    b'json = [];
json[0].a = 1;
',
    b'json.foo = 1;
',  # bare?
    b'json["foo"] = 1;
',
    b'json["\u0041"] = 1;
',  # unicode escape in key?
    b'json = "\u0041";
',  # unicode escape in value?
    b'json = 1.0;
',
    b'json = 1e10;
',
    b'json = -0;
',
    b'json = "hello\nworld";
',
    b'json = "\u001F";
',
    b'json.a = "hi";
json.b = 1;
',  # no root assignment?
    b'json = {};
json.a = 1;
json.b = 2;
',
    b'json = [];
json[0] = "a";
json[1] = "b";
',
    b'  json = 1;
',  # leading space?
    b'	json = 1;
',
    b'json = 1;

json = 2;
',  # blank line?
    b'json = 1;
invalid
',
    b'invalid
json = 1;
',
    b'json = 1;
json.a = 1;
json = 2;
',  # root overwritten?
    b'json = null;
',
    b'json = "a";
json = "b";
',
]
for t in tests:
    rc,out,err = ungron(t)
    print(f"in={t!r} => rc={rc} out={out!r} err={err!r}")
PY

