package main

import (
	"flag"
	"fmt"
	"os"
	"strings"
)

const helpText = "Transform JSON (from a file, URL, or stdin) into discrete assignments to make it greppable\n\nUsage:\n  gron [OPTIONS] [FILE|URL|-]\n\nOptions:\n  -u, --ungron     Reverse the operation (turn assignments back into JSON)\n  -v, --values     Print just the values of provided assignments\n  -c, --colorize   Colorize output (default on tty)\n  -m, --monochrome Monochrome (don't colorize output)\n  -s, --stream     Treat each line of input as a separate JSON object\n  -k, --insecure   Disable certificate validation\n  -x, --proxy      Set proxy configuration\n      --noproxy    Comma-separated list of hosts for which not to use a proxy, if one is specified.\n  -j, --json       Represent gron data as JSON stream\n      --no-sort    Don't sort output (faster)\n      --version    Print version information\n\nExit Codes:\n  0\tOK\n  1\tFailed to open file\n  2\tFailed to read input\n  3\tFailed to form statements\n  4\tFailed to fetch URL\n  5\tFailed to parse statements\n  6\tFailed to encode JSON\n\nExamples:\n  gron /tmp/apiresponse.json\n  gron http://jsonplaceholder.typicode.com/users/1 \n  curl -s http://jsonplaceholder.typicode.com/users/1 | gron\n  gron http://jsonplaceholder.typicode.com/users/1 | grep company | gron --ungron\n"

func isHelpArg(arg string) bool {
	// check if arg is -h, --h, -help, --help with optional =value
	if arg == "-h" || arg == "--h" || arg == "-help" || arg == "--help" {
		return true
	}
	if strings.HasPrefix(arg, "-h=") || strings.HasPrefix(arg, "--h=") || strings.HasPrefix(arg, "-help=") || strings.HasPrefix(arg, "--help=") {
		return true
	}
	return false
}

func main() {
	// pre-scan for help (order-sensitive with errors)
	// we need to know flag types to skip string values
	// boolean flags set
	boolFlags := map[string]bool{
		"u": true, "ungron": true,
		"v": true, "values": true,
		"c": true, "colorize": true,
		"m": true, "monochrome": true,
		"s": true, "stream": true,
		"k": true, "insecure": true,
		"j": true, "json": true,
		"no-sort": true,
		"version": true,
		"h": true, "help": true,
	}
	stringFlags := map[string]bool{
		"x": true, "proxy": true, "noproxy": true,
	}
	args := os.Args[1:]
	// pre-scan
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "--" {
			break
		}
		if arg == "-" || !strings.HasPrefix(arg, "-") || arg == "-" {
			break
		}
		// strip leading dashes
		stripped := strings.TrimLeft(arg, "-")
		// Actually need to handle single - vs --? Both allow any flag name
		// For flag package, -flag and --flag are same, and leading dashes are stripped (one or two)
		// So name is up to = or end
		var name, val string
		var hasVal bool
		if eq := strings.Index(stripped, "="); eq >= 0 {
			name = stripped[:eq]
			val = stripped[eq+1:]
			hasVal = true
		} else {
			name = stripped
			hasVal = false
		}
		// check help first? But need to check unknown before help? Order: first special wins.
		// If this arg is help-like, then help wins (return help) unless earlier error? But we iterate in order, so first help/error wins.
		// So check if help-like
		if name == "h" || name == "help" {
			// any =value is help (even invalid boolean), so return help
			fmt.Fprint(os.Stderr, helpText)
			os.Exit(0)
		}
		// check if defined
		if boolFlags[name] {
			if hasVal {
				// check valid boolean? ParseBool accepts 1,t,T,TRUE,true,True,0,f,F,FALSE,false,False
				// Actually Go's flag uses strconv.ParseBool
				if _, err := parseBool(val); err != nil {
					// invalid boolean value error will be handled by flag package
					// But for pre-scan, this is an error before any later help, so return error?
					// We should let flag package handle it (which will print error+usage and exit 2)
					// To ensure help after this does NOT win, we should exit with error now? Or let flag package handle?
					// Since this is first error before any help, we should let flag package handle (which will print error)
					// But to preserve order, we need to ensure later help is ignored. Since flag package will error on this arg first, it will ignore later help. Good.
					// So we can just break and let flag package handle? Or we can directly handle error here?
					// Simpler: do nothing here, let flag package handle. But need to ensure pre-scan doesn't incorrectly return help for later help.
					// Since we found error first, we should NOT return help for later help. So we should return "error" to indicate error first?
					// Actually we can just return and let flag package handle error by not exiting here, but continuing pre-scan would find later help and incorrectly return help.
					// So we must stop pre-scan on first error and NOT check further for help.
					// So return error indication: we can just exit via flag package? Or we can directly print error and exit?
					// Easiest: if we find error first, we should stop and let flag package handle (which will print error). But to prevent later help from winning, we must NOT continue scanning for help.
					// So we should break pre-scan and proceed to flag.Parse() which will error on this arg.
					// To do that, we can just return "" and proceed to flag.Parse()? But then flag.Parse() will error correctly. However, what if later help exists? flag.Parse() will error on first error, ignoring later help. Good. So we can just break pre-scan on error and proceed.
					// For simplicity, if we detect error in pre-scan, we can just break and proceed to flag.Parse().
					break
