func isIdentifierStart(r rune) bool {
	if r == '$' || r == '_' {
		return true
	}
	if unicode.IsLetter(r) {
		return true
	}
	if unicode.Is(unicode.Nl, r) {
		return true
	}
	return false
}

func isIdentifierPart(r rune) bool {
	if isIdentifierStart(r) {
		return true
	}
	if unicode.IsDigit(r) {
		return true
	}
	if unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Mc, r) || unicode.Is(unicode.Pc, r) {
		return true
	}
	return false
}

func isBareKey(s string) bool {
	if s == "" {
		return false
	}
	if reserved[s] {
		return false
	}
	for i, r := range s {
		if i == 0 {
			if !isIdentifierStart(r) {
				return false
			}
		} else {
			if !isIdentifierPart(r) {
				return false
			}
		}
	}
	return true
}

func quoteString(s string) string {
	var buf bytes.Buffer
	buf.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			buf.WriteString("\\\"")
		case '\\':
			buf.WriteString("\\\\")
		case '\b':
			buf.WriteString("\\b")
		case '\f':
			buf.WriteString("\\f")
		case '\n':
			buf.WriteString("\\n")
		case '\r':
			buf.WriteString("\\r")
		case '\t':
			buf.WriteString("\\t")
		default:
			if r < 0x20 || r == 0x7f || (r >= 0x80 && r <= 0x9f) || r == 0x2028 || r == 0x2029 {
				fmt.Fprintf(&buf, "\\u%04X", r)
			} else {
				buf.WriteRune(r)
			}
		}
	}
	buf.WriteByte('"')
	return buf.String()
}

