func fetchURL(rawURL, proxyFlag, noproxyFlag string, insecure bool) ([]byte, error) {
	// determine proxy
	proxyVisited := isFlagVisited("proxy") || isFlagVisited("x")
	noproxyVisited := isFlagVisited("noproxy")
	var proxyStr string
	var noproxyStr string
	if proxyVisited {
		proxyStr = proxyFlag
	} else {
		// use env: http_proxy for http, https_proxy for https? Only lowercase as observed
		// Determine scheme of rawURL
		lower := strings.ToLower(rawURL)
		if strings.HasPrefix(lower, "https://") {
			proxyStr = os.Getenv("https_proxy")
		} else {
			proxyStr = os.Getenv("http_proxy")
		}
	}
	if noproxyVisited {
		noproxyStr = noproxyFlag
	} else {
		noproxyStr = os.Getenv("no_proxy")
	}
	// custom proxy func
	proxyFunc := func(req *http.Request) (*url.URL, error) {
		// check noproxy exact match with req.URL.Host
		if noproxyStr != "" {
			parts := strings.Split(noproxyStr, ",")
			for _, p := range parts {
				if p == req.URL.Host {
					return nil, nil
				}
			}
		}
		if proxyStr == "" || proxyStr == "-" {
			return nil, nil
		}
		u, err := url.Parse(proxyStr)
		if err != nil {
			return nil, nil
		}
		return u, nil
	}
	tr := &http.Transport{
		Proxy:           proxyFunc,
		TLSClientConfig: &tls.Config{InsecureSkipVerify: insecure},
	}
	client := &http.Client{Transport: tr}
	// set headers
	req, err := http.NewRequest("GET", rawURL, nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("Accept", "application/json")
	req.Header.Set("User-Agent", "gron/dev")
	resp, err := client.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, err
	}
	return body, nil
}

func isFlagVisited(name string) bool {
	found := false
	flag.Visit(func(f *flag.Flag) {
		if f.Name == name {
			found = true
		}
	})
	return found
}
