func jsonPathPlain(path []interface{}) string {
	if len(path) == 0 {
		return "[]"
	}
	var buf bytes.Buffer
	buf.WriteByte('[')
	for i, p := range path {
		if i > 0 {
			buf.WriteByte(',')
		}
		switch v := p.(type) {
		case string:
			buf.WriteString(quoteString(v))
		case int:
			buf.WriteString(strconv.Itoa(v))
		default:
			buf.WriteString(fmt.Sprintf("%v", v))
		}
	}
	buf.WriteByte(']')
	return buf.String()
}

func jsonPathString(path []interface{}, colorize bool) string {
	// for now same as plain, colorize handled elsewhere
	return jsonPathPlain(path)
}

func jsonValuePlain(v interface{}) string {
	switch val := v.(type) {
	case map[string]interface{}:
		if len(val) == 0 {
			// need to distinguish {} vs []? Both empty, but type determines
			return "{}"
		}
		return "{}"
	case []interface{}:
		if len(val) == 0 {
			return "[]"
		}
		return "[]"
	case string:
		return quoteString(val)
	case json.Number:
		return string(val)
	case float64:
		return strconv.FormatFloat(val, 'g', -1, 64)
	case bool:
		if val {
			return "true"
		}
		return "false"
	case nil:
		return "null"
	default:
		return fmt.Sprintf("%v", val)
	}
}

func jsonValueString(v interface{}, colorize bool) string {
	return jsonValuePlain(v)
}

