// genStatements generates gron assignments for value v with prefix.
// It appends to stmts: first the assignment for prefix itself (with {} or [] or value), then recursively for children.
// colorize determines if output should be colorized.
func genStatements(prefix string, v interface{}, stmts *[]string, colorize bool) {
	switch val := v.(type) {
	case map[string]interface{}:
		// empty or not, output prefix = {};
		stmt := ""
		if colorize {
			stmt = colorizePath(prefix) + " = " + colorizeEmpty("{}") + ";"
		} else {
			stmt = prefix + " = {};"
		}
		*stmts = append(*stmts, stmt)
		// for each key, recurse
		for k, child := range val {
			var childPrefix string
			if isBareKey(k) {
				childPrefix = prefix + "." + k
			} else {
				childPrefix = prefix + "[" + quoteString(k) + "]"
			}
			// if colorize, need to handle path colorization later? For now genStatements will colorize path via colorizePath
			genStatements(childPrefix, child, stmts, colorize)
		}
	case []interface{}:
		stmt := ""
		if colorize {
			stmt = colorizePath(prefix) + " = " + colorizeEmpty("[]") + ";"
		} else {
			stmt = prefix + " = [];"
		}
		*stmts = append(*stmts, stmt)
		for i, child := range val {
			childPrefix := fmt.Sprintf("%s[%d]", prefix, i)
			genStatements(childPrefix, child, stmts, colorize)
		}
	case string:
		qs := quoteString(val)
		stmt := ""
		if colorize {
			stmt = colorizePath(prefix) + " = " + colorizeString(qs) + ";"
		} else {
			stmt = prefix + " = " + qs + ";"
		}
		*stmts = append(*stmts, stmt)
	case json.Number:
		s := string(val)
		stmt := ""
		if colorize {
			stmt = colorizePath(prefix) + " = " + colorizeNumber(s) + ";"
		} else {
			stmt = prefix + " = " + s + ";"
		}
		*stmts = append(*stmts, stmt)
	case float64:
		// should not happen with UseNumber, but handle
		s := strconv.FormatFloat(val, 'g', -1, 64)
		stmt := ""
		if colorize {
			stmt = colorizePath(prefix) + " = " + colorizeNumber(s) + ";"
		} else {
			stmt = prefix + " = " + s + ";"
		}
		*stmts = append(*stmts, stmt)
	case bool:
		s := "false"
		if val {
			s = "true"
		}
		stmt := ""
		if colorize {
			stmt = colorizePath(prefix) + " = " + colorizeBool(s) + ";"
		} else {
			stmt = prefix + " = " + s + ";"
		}
		*stmts = append(*stmts, stmt)
	case nil:
		stmt := ""
		if colorize {
			stmt = colorizePath(prefix) + " = " + colorizeBool("null") + ";"
		} else {
			stmt = prefix + " = null;"
		}
		*stmts = append(*stmts, stmt)
	default:
		// unknown, treat as string?
		s := fmt.Sprintf("%v", val)
		stmt := prefix + " = " + s + ";"
		*stmts = append(*stmts, stmt)
	}
}

func colorizePath(path string) string {
	// path like "json", "json.a", "json[0]", "json.a[0].b", "json[\"a-b\"]"
	// Need to colorize identifiers blue, brackets magenta, strings yellow, numbers red
	// Approach: parse path into tokens and colorize each
	// Path always starts with "json" or other root? For gron, root is always "json". For stream, prefix is "json[0]" etc. So first token is identifier.
	// We'll parse sequentially: identifier, then (.identifier or [index/string])*
	if !strings.HasPrefix(path, "") {
		return path
	}
	var buf bytes.Buffer
	i := 0
	// parse first identifier (up to . or [)
	j := 0
	for j < len(path) && path[j] != '.' && path[j] != '[' {
		j++
	}
	ident := path[i:j]
	buf.WriteString(colorizeBare(ident))
	i = j
	for i < len(path) {
		if path[i] == '.' {
			buf.WriteByte('.')
			i++
			j = i
			for j < len(path) && path[j] != '.' && path[j] != '[' {
				j++
			}
			ident = path[i:j]
			buf.WriteString(colorizeBare(ident))
			i = j
		} else if path[i] == '[' {
			// find matching ]
			// content is either number or quoted string
			// find closing ]
			k := strings.Index(path[i:], "]")
			if k < 0 {
				buf.WriteString(path[i:])
				break
			}
			k += i
			inner := path[i+1 : k]
			buf.WriteString(colorizeBracket("["))
			if strings.HasPrefix(inner, "\"") {
				buf.WriteString(colorizeString(inner))
			} else {
				// number index
				buf.WriteString(colorizeNumber(inner))
			}
			buf.WriteString(colorizeBracket("]"))
			i = k + 1
		} else {
			buf.WriteString(path[i:])
			break
		}
	}
	return buf.String()
}

func genJSONLines(path []interface{}, v interface{}, lines *[]string, colorize bool, _ bool) {
	// path is array of keys (strings or ints)
	// value is the JSON value
	// line is [path, value] where path is JSON array, value is JSON value (with numbers preserved, strings quoted, etc.)
