func colorizePath(path string) string {
	var buf bytes.Buffer
	i := 0
	j := 0
	for j < len(path) && path[j] != '.' && path[j] != '[' {
		j++
	}
	ident := path[i:j]
	buf.WriteString(colorizeBare(ident))
	i = j
	for i < len(path) {
		if path[i] == '.' {
			buf.WriteByte('.')
			i++
			j = i
			for j < len(path) && path[j] != '.' && path[j] != '[' {
				j++
			}
			ident = path[i:j]
			buf.WriteString(colorizeBare(ident))
			i = j
		} else if path[i] == '[' {
			k := strings.Index(path[i:], "]")
			if k < 0 {
				buf.WriteString(path[i:])
				break
			}
			k += i
			inner := path[i+1 : k]
			buf.WriteString(colorizeBracket("["))
			if strings.HasPrefix(inner, "\"") {
				buf.WriteString(colorizeString(inner))
			} else {
				buf.WriteString(colorizeNumber(inner))
			}
			buf.WriteString(colorizeBracket("]"))
			i = k + 1
		} else {
			buf.WriteString(path[i:])
			break
		}
	}
	return buf.String()
}

func colorizeStatement(plain string) string {
	idx := strings.Index(plain, " = ")
	if idx < 0 {
		return plain
	}
	path := plain[:idx]
	rest := plain[idx+3:]
	if !strings.HasSuffix(rest, ";") {
		return plain
	}
	val := rest[:len(rest)-1]
	cpath := colorizePath(path)
	var cval string
	if val == "{}" || val == "[]" {
		cval = colorizeEmpty(val)
	} else if len(val) > 0 && val[0] == '"' {
		cval = colorizeString(val)
	} else if val == "true" || val == "false" || val == "null" {
		cval = colorizeBool(val)
	} else {
		cval = colorizeNumber(val)
	}
	return cpath + " = " + cval + ";"
}

func genStatementsPlain(prefix string, v interface{}, stmts *[]string) {
	switch val := v.(type) {
	case map[string]interface{}:
		*stmts = append(*stmts, prefix+" = {};")
		for k, child := range val {
			var childPrefix string
			if isBareKey(k) {
				childPrefix = prefix + "." + k
			} else {
				childPrefix = prefix + "[" + quoteString(k) + "]"
			}
			genStatementsPlain(childPrefix, child, stmts)
		}
	case []interface{}:
		*stmts = append(*stmts, prefix+" = [];")
		for i, child := range val {
			childPrefix := fmt.Sprintf("%s[%d]", prefix, i)
			genStatementsPlain(childPrefix, child, stmts)
		}
	case string:
		*stmts = append(*stmts, prefix+" = "+quoteString(val)+";")
	case json.Number:
		*stmts = append(*stmts, prefix+" = "+string(val)+";")
	case float64:
		s := strconv.FormatFloat(val, 'g', -1, 64)
		*stmts = append(*stmts, prefix+" = "+s+";")
	case bool:
		if val {
			*stmts = append(*stmts, prefix+" = true;")
		} else {
			*stmts = append(*stmts, prefix+" = false;")
		}
	case nil:
		*stmts = append(*stmts, prefix+" = null;")
	default:
		*stmts = append(*stmts, prefix+" = "+fmt.Sprintf("%v", val)+";")
	}
}

