func jsonPathPlain(path []interface{}) string {
	if len(path) == 0 {
		return "[]"
	}
	var buf bytes.Buffer
	buf.WriteByte('[')
	for i, p := range path {
		if i > 0 {
			buf.WriteByte(',')
		}
		switch v := p.(type) {
		case string:
			buf.WriteString(quoteString(v))
		case int:
			buf.WriteString(strconv.Itoa(v))
		default:
			buf.WriteString(fmt.Sprintf("%v", v))
		}
	}
	buf.WriteByte(']')
	return buf.String()
}
func jsonValuePlain(v interface{}) string {
	switch val := v.(type) {
	case map[string]interface{}:
		return "{}"
	case []interface{}:
		return "[]"
	case string:
		return quoteString(val)
	case json.Number:
		return string(val)
	case float64:
		return strconv.FormatFloat(val, 'g', -1, 64)
	case bool:
		if val {
			return "true"
		}
		return "false"
	case nil:
		return "null"
	default:
		return fmt.Sprintf("%v", val)
	}
}

